assert(state.engine && state.images && state.source.manta.binarySha256);
for (const v of ["manta", "wings"]) {
  let ready = false;
  for (let attempt = 0; attempt < 60; attempt++) {
    try {
      inner(
        "exec",
        v,
        "/bin/busybox",
