  inner("network", "connect", network, "benchmark-runner");
const report = {
  schemaVersion: 2,
  measuredOn: new Date().toISOString().slice(0, 10),
  startedAt: new Date().toISOString(),
  source: state.source,
  engine: state.engine,
  images: state.images,
